import { mapState } from 'vuex';
import {
  supplierFinanceInfo,
  supplierFlowingWaterMark,
  getSupplierList,
  exportTableList,
} from '@/api/supplier';
import exportExcel from '@/utils/newToExcel.js';
import timeOptions from '@/utils/timeOptions';
export default {
  name: 'order',
  data() {
    return {
      modalmark: false,
      remarks: {
        mark: '',
      },
      supplierList: [],
      total: 0,
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      columns: [
        {
          title: '交易单号',
          key: 'order_id',
          minWidth: 180,
        },
        {
          title: '关联订单',
          key: 'link_id',
          minWidth: 180,
        },
        {
          title: '交易时间',
          key: 'trade_time',
          minWidth: 150,
        },
        {
          title: '交易金额',
          slot: 'number',
          minWidth: 80,
        },
        {
          title: '交易人',
          slot: 'user_nickname',
          ellipsis: true,
          minWidth: 80,
        },
        {
          title: '供应商',
          key: 'supplier_name',
          minWidth: 80,
        },
        {
          title: '交易类型',
          key: 'type_name',
          minWidth: 80,
        },
        {
          title: '支付方式',
          key: 'pay_type_name',
          minWidth: 80,
        },
        {
          title: '备注',
          key: 'remark',
          minWidth: 120,
        },
        {
          title: '操作',
          slot: 'action',
          fixed: 'right',
          minWidth: 80,
          align: 'center',
        },
      ],
      orderList: [],
      formValidate: {
        supplier_id: '',
        keyword: '',
        data: '',
        page: 1,
        limit: 20,
      },
      timeVal: [],
      options: timeOptions,
    };
  },
  computed: {
    ...mapState('admin/layout', ['isMobile']),
    labelWidth() {
      return this.isMobile ? undefined : 90;
    },
    labelPosition() {
      return this.isMobile ? 'top' : 'left';
    },
  },
  mounted() {
    this.getList();
    this.getSupplierList();
  },
  methods: {
    getList() {
      this.loading = true;
      supplierFinanceInfo(this.formValidate).then((res) => {
        this.orderList = res.data.list;
        this.total = res.data.count;
        this.loading = false;
      });
    },
    getSupplierList() {
      getSupplierList().then((res) => {
        this.supplierList = res.data;
      });
    },
    search() {
      this.formValidate.page = 1;
      this.getList();
    },
    reset() {
      this.formValidate = {
        supplier_id: '',
        keyword: '',
        data: '',
        page: 1,
        limit: 20,
      };
      this.timeVal = [];
      this.getList();
    },
    // 选择时间
    selectChange(tab) {
      this.formValidate.page = 1;
      this.formValidate.data = tab;
      this.timeVal = [];
      this.getList();
    },
    // 具体日期
    onchangeTime(e) {
      this.timeVal = e;
      this.formValidate.data = this.timeVal[0] ? this.timeVal.join('-') : '';
      this.formValidate.page = 1;
      this.getList();
    },
    //分页
    pageChange(status) {
      this.formValidate.page = status;
      this.getList();
    },
    remark(e) {
      this.remarkId = e.id;
      this.modalmark = true;
      this.remarks.mark = e.remark;
    },
    //备注的提交
    putRemark() {
      this.modalmark = false;
      supplierFlowingWaterMark(this.remarkId, this.remarks)
        .then((res) => {
          this.$Message.success(res.msg);
          this.remarks = { mark: '' };
          this.modalmark = false;
          this.getList();
        })
        .catch((err) => {
          this.$Message.error(err.msg);
          this.modalmark = false;
        });
    },
    // 取消备注按钮
    cancel() {
      this.remarks = { mark: '' };
      this.modalmark = false;
    },
    //导出
    async exports() {
      let [th, filekey, data, fileName] = [[], [], [], ''];
      let supplier_id = this.formValidate.supplier_id,
        keyword = this.formValidate.keyword,
        date = this.formValidate.data;
      let lebData = await this.getExcelData({ supplier_id, keyword, date });
      if (!fileName) fileName = lebData.filename;
      filekey = lebData.filekey;
      if (!th.length) th = lebData.header; //表头
      data = data.concat(lebData.export);
      exportExcel(th, filekey, fileName, data);
    },
    getExcelData(data) {
      return new Promise((resolve) => {
        exportTableList(data).then((res) => resolve(res.data));
      });
    },
  },
};
